//! Replays the golden corpus generated by
//! `electricity/scripts/generate_adapter_corpus.py` -- real output
//! from Circuitry's own `circuitry.adapters.*` (request building via
//! a monkeypatched `run_curl`, and outcome interpretation via
//! scripted `(returncode, stdout, stderr)` triples) against this
//! crate's own pure halves (`ollama::build_request`/
//! `ollama::interpret_outcome`, `openai_compat::chat_messages`/
//! `sampling_fields`/`interpret_outcome`, `openai::interpret_outcome`,
//! `anthropic::build_request_body`/`interpret_outcome`,
//! `replicate::interpret_outcome`), plus the pure helpers in
//! `curl_text.rs`.
//!
//! Parsed with `electricity_json::loads`, not `serde_json`: the
//! corpus's own nested JSON objects (a `format:` schema under
//! `params`, for one) have to keep their source key order the same
//! way Python's own `json.loads` always does, and `serde_json`'s
//! default `Map` only preserves order with its `preserve_order`
//! feature, which this crate's own dev-dependency set deliberately
//! does not turn on workspace-wide.
//!
//! The corpus is checked in (`tests/golden/adapter_corpus.json`); CI
//! separately regenerates it with Python 3.11 under the pinned
//! generator constraints and fails the build if it differs
//! (`.github/workflows/electricity-generated.yml`), so this test only
//! needs to trust the committed file.

use electricity_adapters::curl_text::{
    classify_curl_outcome, curl_failure_message, parse_error_body, parse_error_code,
};
use electricity_adapters::transport::CurlOutcome;
use electricity_adapters::{anthropic, ollama, openai, openai_compat, replicate};
use electricity_value::{Dict, Value};
use electricity_vm::adapter::{ChatMessage, GenerateOptions, ImageInput};
use electricity_vm::retry::RetryInfo;
use std::fs;

fn corpus() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/golden/adapter_corpus.json"
    );
    let text = fs::read_to_string(path).expect("adapter_corpus.json must exist");
    electricity_json::loads(&text).expect("adapter_corpus.json must be valid JSON")
}

fn get<'a>(v: &'a Value, key: &str) -> &'a Value {
    static NONE: Value = Value::None;
    v.as_dict()
        .and_then(|d| d.get(&Value::Str(key.to_string())))
        .unwrap_or(&NONE)
}

fn list<'a>(v: &'a Value, key: &str) -> &'a [Value] {
    get(v, key).as_list().unwrap_or(&[])
}

fn str_opt(v: &Value) -> Option<String> {
    v.as_str().map(String::from)
}

fn i64_opt(v: &Value) -> Option<i64> {
    match v {
        Value::Int(i) => i.to_bigint().to_string().parse::<i64>().ok(),
        _ => None,
    }
}

fn u32_val(v: &Value) -> u32 {
    i64_opt(v).unwrap() as u32
}

fn bool_val(v: &Value) -> bool {
    matches!(v, Value::Bool(true))
}

fn options_from_json(spec: &Value) -> GenerateOptions {
    let temperature = match get(spec, "temperature") {
        Value::None => None,
        Value::Str(s) if s == "NaN" => Some(f64::NAN),
        Value::Float(f) => Some(*f),
        v @ Value::Int(_) => Some(v.as_float().unwrap()),
        _ => None,
    };
    let max_tokens = i64_opt(get(spec, "max_tokens"));
    let stop: Vec<String> = list(spec, "stop")
        .iter()
        .filter_map(Value::as_str)
        .map(String::from)
        .collect();
    let params = match get(spec, "params") {
        Value::None => Value::Dict(Dict::new()),
        other => other.clone(),
    };
    let deterministic = bool_val(get(spec, "deterministic"));
    let messages: Vec<ChatMessage> = list(spec, "messages")
        .iter()
        .map(|m| ChatMessage {
            role: get(m, "role").as_str().unwrap().to_string(),
            content: get(m, "content").as_str().unwrap().to_string(),
        })
        .collect();
    let images: Vec<ImageInput> = list(spec, "images")
        .iter()
        .map(|img| ImageInput {
            data: str_opt(get(img, "data_hex")).map(|hex| hex_decode(&hex)),
            media_type: str_opt(get(img, "media_type")),
            url: str_opt(get(img, "url")),
        })
        .collect();
    GenerateOptions {
        temperature,
        max_tokens,
        stop,
        params,
        deterministic,
        messages,
        images,
        json_schema: None,
    }
}

fn hex_decode(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

fn dumps(value: &Value) -> String {
    electricity_json::dumps(value, electricity_json::WriteMode::COMPACT).unwrap()
}

/// `normalize.py::canonicalize_http_headers` -- lowercased names, the
/// whole set order-insensitive, `User-Agent` dropped (curl's and
/// electricity's own transport add it after every adapter's own
/// explicit header set is built; neither side's recorded headers here
/// ever include it, so this is the same defensive filter that
/// function applies, not a case this corpus actually exercises).
fn canonicalize_headers(headers: &[(String, String)]) -> Vec<(String, String)> {
    let mut pairs: Vec<(String, String)> = headers
        .iter()
        .filter(|(name, _)| !name.eq_ignore_ascii_case("user-agent"))
        .map(|(name, value)| (name.to_lowercase(), value.clone()))
        .collect();
    pairs.sort();
    pairs
}

/// The corpus's own `headers` field -- a plain JSON object
/// (`curl_support.run_curl`'s own `headers: dict[str, str]` parameter),
/// read as `(name, value)` pairs.
fn headers_from_case(case: &Value) -> Vec<(String, String)> {
    get(case, "headers")
        .as_dict()
        .map(|d| {
            d.iter()
                .map(|(k, v)| (k.py_str(), v.as_str().unwrap().to_string()))
                .collect()
        })
        .unwrap_or_default()
}

fn assert_headers_match_expected(actual: &[(String, String)], case: &Value, context: &str) {
    assert_eq!(
        canonicalize_headers(actual),
        canonicalize_headers(&headers_from_case(case)),
        "{context}: headers"
    );
}

fn outcome_from_case(case: &Value) -> CurlOutcome {
    let returncode = i64_opt(get(case, "returncode")).unwrap() as i32;
    let stdout = get(case, "stdout").as_str().unwrap().to_string();
    let stderr = get(case, "stderr").as_str().unwrap().to_string();
    let status = if returncode == 22 {
        stderr
            .rsplit(' ')
            .next()
            .and_then(|s| s.parse::<u16>().ok())
    } else {
        None
    };
    CurlOutcome {
        returncode,
        stdout,
        stderr,
        status,
        retry_after: None,
    }
}

#[derive(Debug)]
enum ExpectedOutcome {
    Ok {
        text: String,
        tokens_sent: Option<i64>,
        tokens_received: Option<i64>,
        finish_reason: Option<String>,
    },
    Err {
        class: String,
        message: String,
        retry: RetryInfo,
    },
}

fn retry_info_from_json(retry: &Value) -> RetryInfo {
    RetryInfo {
        retryable: bool_val(get(retry, "retryable")),
        status: i64_opt(get(retry, "status")).map(|s| s as u16),
        retry_after: str_opt(get(retry, "retry_after")),
        error_code: str_opt(get(retry, "error_code")),
    }
}

fn expected_from_result(result: &Value) -> ExpectedOutcome {
    if bool_val(get(result, "ok")) {
        ExpectedOutcome::Ok {
            text: get(result, "text").as_str().unwrap().to_string(),
            tokens_sent: i64_opt(get(result, "tokens_sent")),
            tokens_received: i64_opt(get(result, "tokens_received")),
            finish_reason: str_opt(get(result, "finish_reason")),
        }
    } else {
        ExpectedOutcome::Err {
            class: get(result, "class").as_str().unwrap().to_string(),
            message: get(result, "message").as_str().unwrap().to_string(),
            retry: retry_info_from_json(get(result, "retry")),
        }
    }
}

fn assert_matches_expected(
    actual: Result<electricity_vm::adapter::GenerateResult, electricity_vm::adapter::AdapterError>,
    expected: &ExpectedOutcome,
    context: &str,
) {
    match (actual, expected) {
        (
            Ok(result),
            ExpectedOutcome::Ok {
                text,
                tokens_sent,
                tokens_received,
                finish_reason,
            },
        ) => {
            assert_eq!(&result.text, text, "{context}: text");
            assert_eq!(&result.tokens_sent, tokens_sent, "{context}: tokens_sent");
            assert_eq!(
                &result.tokens_received, tokens_received,
                "{context}: tokens_received"
            );
            assert_eq!(
                &result.finish_reason, finish_reason,
                "{context}: finish_reason"
            );
        }
        (
            Err(err),
            ExpectedOutcome::Err {
                class,
                message,
                retry,
            },
        ) => {
            assert_eq!(&err.message, message, "{context}: message");
            assert_eq!(err.py_class.name(), class.as_str(), "{context}: class");
            assert_eq!(&err.retry, retry, "{context}: retry");
        }
        (actual, expected) => {
            panic!("{context}: mismatched shape -- actual={actual:?}, expected={expected:?}");
        }
    }
}

// ---------------------------------------------------------------------
// 1. Pure helpers.
// ---------------------------------------------------------------------

#[test]
fn parse_error_body_matches_circuitry() {
    for case in list(&corpus(), "parse_error_body_cases") {
        let stdout = get(case, "stdout").as_str().unwrap();
        let expected = str_opt(get(case, "expected"));
        assert_eq!(parse_error_body(stdout), expected, "stdout={stdout:?}");
    }
}

#[test]
fn parse_error_code_matches_circuitry() {
    for case in list(&corpus(), "parse_error_code_cases") {
        let stdout = get(case, "stdout").as_str().unwrap();
        let expected = str_opt(get(case, "expected"));
        assert_eq!(parse_error_code(stdout), expected, "stdout={stdout:?}");
    }
}

#[test]
fn curl_failure_message_matches_circuitry() {
    for case in list(&corpus(), "curl_failure_message_cases") {
        let secrets: Vec<&str> = list(case, "secrets")
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        let model = get(case, "model").as_str();
        let message = curl_failure_message(
            get(case, "source").as_str().unwrap(),
            model,
            get(case, "url").as_str().unwrap(),
            i64_opt(get(case, "returncode")).unwrap() as i32,
            get(case, "stdout").as_str().unwrap(),
            get(case, "stderr").as_str().unwrap(),
            get(case, "hint").as_str().unwrap(),
            &secrets,
        );
        assert_eq!(message, get(case, "expected").as_str().unwrap());
    }
}

// ---------------------------------------------------------------------
// 2. Native Ollama.
// ---------------------------------------------------------------------

#[test]
fn ollama_request_building_matches_circuitry() {
    for case in list(&corpus(), "ollama_request_cases") {
        let spec = get(case, "spec");
        let model = get(spec, "model").as_str().unwrap();
        let prompt = get(spec, "prompt").as_str().unwrap();
        let options = options_from_json(get(spec, "options"));
        let (endpoint, payload) = ollama::build_request(model, prompt, &options).unwrap();
        let url = format!("http://localhost:11434{endpoint}");
        assert_eq!(url, get(case, "url").as_str().unwrap(), "spec={spec:?}");
        assert_eq!(
            dumps(&Value::Dict(payload)),
            get(case, "data").as_str().unwrap(),
            "spec={spec:?}"
        );
        // The recorded headers are compared
        // against the adapter's own `ollama::request_headers()`, the
        // same function `generate()` itself calls, never a list
        // written by hand in the test a second time.
        assert_headers_match_expected(
            &ollama::request_headers(),
            case,
            &format!("ollama request {spec:?}"),
        );
    }
}

#[test]
fn ollama_outcome_interpretation_matches_circuitry() {
    for case in list(&corpus(), "ollama_outcome_cases") {
        let outcome = outcome_from_case(case);
        let model = get(case, "model").as_str().unwrap();
        let timeout_seconds = u32_val(get(case, "timeout_seconds"));
        let base_url = get(case, "base_url").as_str().unwrap();
        let url = format!("{base_url}/api/generate");
        let actual = ollama::interpret_outcome(&outcome, model, timeout_seconds, base_url, &url);
        let expected = expected_from_result(get(case, "result"));
        assert_matches_expected(actual, &expected, &format!("ollama outcome {case:?}"));
    }
}

// ---------------------------------------------------------------------
// 3. The OpenAI-compatible family.
// ---------------------------------------------------------------------

#[test]
fn openai_compat_request_building_matches_circuitry() {
    for case in list(&corpus(), "openai_compat_request_cases") {
        let spec = get(case, "spec");
        let prompt = get(spec, "prompt").as_str().unwrap();
        let options = options_from_json(get(spec, "options"));
        let configured_model = get(spec, "model").as_str().unwrap();
        let payload = openai_compat::build_request(configured_model, prompt, &options);
        assert_eq!(
            dumps(&Value::Dict(payload)),
            get(case, "data").as_str().unwrap(),
            "spec={spec:?}"
        );
        // `LMStudioAdapter` carries no `api_key_env`, so every case
        // here sends only the one static header -- compared against
        // `openai_compat::request_headers`, the same function
        // `chat_completion()` itself calls, plus
        // the fixed URL every case here was recorded against.
        assert_headers_match_expected(
            &openai_compat::request_headers("", &[]),
            case,
            &format!("openai_compat request {spec:?}"),
        );
        assert_eq!(
            get(case, "url").as_str().unwrap(),
            "http://localhost:1234/v1/chat/completions",
            "spec={spec:?}"
        );
    }
}

#[test]
fn openai_compat_outcome_interpretation_matches_circuitry() {
    for case in list(&corpus(), "openai_compat_outcome_cases") {
        let outcome = outcome_from_case(case);
        let model = get(case, "model").as_str().unwrap();
        let actual = openai_compat::interpret_outcome(
            "OpenAI-compatible",
            &outcome,
            model,
            "http://localhost:1234/v1/chat/completions",
            &[],
        );
        let expected = expected_from_result(get(case, "result"));
        assert_matches_expected(
            actual,
            &expected,
            &format!("openai_compat outcome {case:?}"),
        );
    }
}

