// ---------------------------------------------------------------------
// 6. `replicate`.
// ---------------------------------------------------------------------

#[test]
fn replicate_request_building_matches_circuitry() {
    for case in list(&corpus(), "replicate_request_cases") {
        let model = get(case, "model").as_str().unwrap();
        let mut input = Dict::new();
        input.insert(
            Value::Str("prompt".to_string()),
            Value::Str("hi".to_string()),
        );
        let mut payload = Dict::new();
        payload.insert(Value::Str("input".to_string()), Value::Dict(input));
        assert_eq!(
            dumps(&Value::Dict(payload)),
            get(case, "data").as_str().unwrap(),
            "model={model}"
        );
        let expected_url = format!("https://api.replicate.com/v1/models/{model}/predictions");
        assert_eq!(expected_url, get(case, "url").as_str().unwrap());
    }
}

#[test]
fn replicate_outcome_interpretation_matches_circuitry() {
    for case in list(&corpus(), "replicate_outcome_cases") {
        let outcome = outcome_from_case(case);
        let model = get(case, "model").as_str().unwrap();
        let wait = i64_opt(get(case, "wait")).unwrap();
        let options = GenerateOptions::default();
        let actual = replicate::interpret_outcome(
            &outcome,
            model,
            "https://api.replicate.com/v1/models/meta/llama/predictions",
            "circuitry-test-fake-token",
            wait,
            &options,
        );
        let expected = expected_from_result(get(case, "result"));
        assert_matches_expected(actual, &expected, &format!("replicate outcome {case:?}"));
    }
}

#[test]
fn classify_curl_outcome_is_exercised_by_every_outcome_case() {
    // A cheap sanity check that every recorded outcome case's own
    // `returncode` is one this crate's exit-code table actually
    // knows how to classify (never panics), tying the corpus to
    // `curl_text::classify_curl_outcome` directly rather than only
    // indirectly through each adapter's own `interpret_outcome`.
    let data = corpus();
    for key in [
        "ollama_outcome_cases",
        "openai_compat_outcome_cases",
        "openai_outcome_cases",
        "anthropic_outcome_cases",
        "replicate_outcome_cases",
    ] {
        for case in list(&data, key) {
            let outcome = outcome_from_case(case);
            let _ = classify_curl_outcome(&outcome);
        }
    }
}
